"""Guard the split between authored files and whole generated files.

Only a complete machine-generated file may be exempt from the authored-file
budget, so a generated block spliced into a hand-written module is not allowed
to grow; this test keeps the generated files whole and the list of hosts that
still carry a spliced block shrinking. The exemption is keyed by path in
.gitattributes, so a hand-written file under a fake `// GENERATED` header would
slip the budget; every exempt path must therefore be one the generators write
(their own output lists are the single source), apart from lockfiles, the
changelog and the skills/vow/ mirror.
"""

import fnmatch
import re
import shutil
import subprocess
import tempfile
import unittest
from pathlib import Path

import generate_help
import generate_operations
import spec_assemble

REPO = Path(__file__).resolve().parent.parent
GENERATED_GLOBS = (
    "compiler/*_gen.vow",
    "compiler/tests/*_gen.vow",
    "vow/src/skill_gen/*.rs",
)
HEADER_PREFIX = "// GENERATED by scripts/"
MAX_GENERATED_BYTES = 450_000
MARKER = re.compile(r"^\s*// GENERATE:[A-Z_]+:START\s*$", re.MULTILINE)
SOURCE_ROOTS = ("compiler/", "vow/", "vow-")
IGNORE_ATTRIBUTE = "token-limit-ignore"

# Exempt from the authored-file budget for reasons other than being a generator
# output: lockfiles, the release changelog and the skills/vow/ mirror.
ALLOWED_EXEMPT = {"Cargo.lock", "bench/uv.lock", "workflow/uv.lock", "CHANGELOG.md"}
ALLOWED_EXEMPT_PREFIXES = ("skills/vow/",)

# Hosts that still carry a spliced `// GENERATE:` block. Splitting one and moving its
# block into a generated module removes it from this set; nothing may be added.
DEFERRED_HOSTS = {
    "compiler/c_emitter.vow",
    "compiler/lower.vow",
    "vow-clif-shim/src/lib.rs",
    "vow-codegen/src/cranelift_backend.rs",
    "vow-ir/src/lower/mod.rs",
    "vow-ir/src/region.rs",
    "vow-types/src/env.rs",
    "vow-verify/src/c_emitter.rs",
}


def tracked_files(repo: Path = REPO) -> list[str]:
    out = subprocess.run(
        ["git", "ls-files", "-z"],
        cwd=repo,
        stdout=subprocess.PIPE,
        check=True,
    ).stdout
    return [p for p in out.decode().split("\0") if p]


def exempt_files(repo: Path = REPO) -> list[str]:
    """Tracked files Git resolves to `token-limit-ignore`, as the budget check does."""
    out = subprocess.run(
        ["git", "check-attr", "-z", "--stdin", IGNORE_ATTRIBUTE],
        cwd=repo,
        input="\0".join(tracked_files(repo)).encode(),
        stdout=subprocess.PIPE,
        check=True,
    ).stdout
    fields = out.decode().split("\0")
    triples = zip(fields[0::3], fields[2::3])
    return [path for path, value in triples if value not in ("unspecified", "unset")]


def generator_outputs() -> set[str]:
    """Every file a generator writes, taken from the generators themselves."""
    return (
        generate_help.generated_output_paths()
        | generate_operations.generated_output_paths()
        | {spec_assemble.target_name(doc) for doc in spec_assemble.doc_names()}
    )


def stray_exempt_files(exempt: list[str], outputs: set[str]) -> list[str]:
    """Budget-exempt files that no generator writes and no allowance covers."""
    return sorted(
        path
        for path in exempt
        if path not in outputs
        and path not in ALLOWED_EXEMPT
        and not path.startswith(ALLOWED_EXEMPT_PREFIXES)
    )


def is_generated(path: str) -> bool:
    return any(fnmatch.fnmatch(path, glob) for glob in GENERATED_GLOBS)


def source_files() -> list[str]:
    return [
        p
        for p in tracked_files()
        if p.endswith((".vow", ".rs")) and p.startswith(SOURCE_ROOTS)
    ]


class GeneratedLayoutTests(unittest.TestCase):
    def test_generated_files_carry_the_header_and_stay_small(self):
        for path in (p for p in source_files() if is_generated(p)):
            data = (REPO / path).read_bytes()
            with self.subTest(path=path):
                self.assertTrue(data.startswith(HEADER_PREFIX.encode()), path)
                self.assertLessEqual(len(data), MAX_GENERATED_BYTES, path)

    def test_generated_globs_are_exempt_in_gitattributes(self):
        attributes = (REPO / ".gitattributes").read_text().splitlines()
        exempt = {
            line.split()[0] for line in attributes if "token-limit-ignore" in line
        }
        for glob in GENERATED_GLOBS:
            self.assertIn(glob, exempt)

    def test_every_budget_exempt_file_is_a_generator_output(self):
        self.assertEqual(
            stray_exempt_files(exempt_files(), generator_outputs()),
            [],
            "hand-written file exempt from the 20 KB authored-file budget",
        )

    def test_generator_outputs_cover_each_generator(self):
        outputs = generator_outputs()
        for path in (
            "compiler/help_text_gen.vow",
            "compiler/skill_text_gen.vow",
            "vow/src/skill_gen/help_text.rs",
            "compiler/catalogue_vc_ops_gen.vow",
            "compiler/tests/catalogue_facts_gen.vow",
            "docs/spec/grammar.md",
            "docs/spec/operations.json",
        ):
            self.assertIn(path, outputs)

    def test_stray_gen_module_under_a_fake_header_is_rejected(self):
        outputs = generator_outputs()
        with tempfile.TemporaryDirectory() as tmp:
            repo = Path(tmp)
            subprocess.run(["git", "init", "-q"], cwd=repo, check=True)
            shutil.copy(REPO / ".gitattributes", repo)
            fakes = {
                "compiler/zz_gen.vow": "// GENERATED by scripts/generate_help.py\n",
                "compiler/tests/zz_gen.vow": "// GENERATED by scripts/x.py\n",
                "vow/src/skill_gen/zz.rs": "// GENERATED by scripts/x.py\n",
                "docs/spec/cli.md": "authored\n",
            }
            for rel, text in fakes.items():
                (repo / rel).parent.mkdir(parents=True, exist_ok=True)
                (repo / rel).write_text(text + "x\n" * 100_000)
            subprocess.run(["git", "add", "-A"], cwd=repo, check=True)
            strays = stray_exempt_files(exempt_files(repo), outputs)
        self.assertEqual(
            strays,
            [
                "compiler/tests/zz_gen.vow",
                "compiler/zz_gen.vow",
                "vow/src/skill_gen/zz.rs",
            ],
        )

    def test_compiler_modules_are_not_mistaken_for_tests(self):
        # `vowc test compiler/` runs every test_*.vow and *_test.vow it finds, so a
        # driver module named like `main_test.vow` would be run as a test.
        for path in tracked_files():
            parts = path.split("/")
            if len(parts) == 2 and parts[0] == "compiler" and path.endswith(".vow"):
                self.assertFalse(parts[1].endswith("_test.vow"), path)

    def test_no_new_authored_file_carries_a_spliced_block(self):
        hosts = {
            p
            for p in source_files()
            if not is_generated(p) and MARKER.search((REPO / p).read_text())
        }
        self.assertEqual(hosts - DEFERRED_HOSTS, set(), "new spliced host")

    def test_deferred_hosts_still_carry_a_block(self):
        for path in sorted(DEFERRED_HOSTS):
            with self.subTest(path=path):
                self.assertTrue(MARKER.search((REPO / path).read_text()), path)


if __name__ == "__main__":
    unittest.main()
